    "id": "real-2005-q37",
    "year": 2005,
    "number": 37,
    "subject": "当代",
    "score": 10,
    "text": "本题为选做题，请在Ⅰ、Ⅱ两道试题中选取其中一道作答，若两题都回答，只按第Ⅰ道试题的成绩记入总分。\n选做题Ⅰ：\n材料1：\n11月下旬，由于反对派质疑总统选举第二轮投票结果，乌克兰爆发了一场空前的政治危机。……莫斯科最难以容忍西方打着民主的旗号插手独联体国家的选举。……格鲁吉亚已经是前车之鉴，如果“玫瑰革命”在乌克兰再度得手，多米诺骨牌效应很可能会冲击其他独联体国家。如此一来，俄罗斯苦苦经营的独联体战略空间将不复存在。……乌克兰大选危机发生后，欧盟采取了与俄罗斯的支持态度完全相反的立场，立即以十分坚定强硬的态度对大选结果表示反对。……同欧盟以往处理热点问题时常常表现出的犹豫不决，议而难决的情景不同，欧盟在处理乌克兰危机时却态度坚决，行动迅速，……欧盟自今年5月扩大至25国后，乌克兰成为欧盟的直接邻国。\n摘自《人民日报》2004年12月10日\n材料2：\n北约是在1949年为对抗苏联而成立的。冷战结束后，北约无视俄罗斯的强烈反对，于1999年接纳波兰、捷克和匈牙利3国加入该组织。今年3月29日，美国国务卿鲍威尔从保加利亚、罗马尼亚、斯洛伐克、斯洛文尼亚、爱沙尼亚、拉脱维亚、立陶宛7国领导人手中接过入约批准书，布什还会见了他们，这标志着北约由19国扩展到26国，从波罗的海到黑海的纵向防线被打通，其东部边界向前推进了1000多公里。\n摘自《当代世界》2004年第5期\n请结合地图和所给材料分析乌克兰的重要战略地位及俄欧、俄美之间的战略利益冲突。\n选做题Ⅱ：\n材料1\n世界石油经济战略态势（截至2003年底）\n材料2\n我国石油的总资源量约为940亿吨，可开采资源量约是160亿吨。50多年来，仅找到60亿吨可采储量，这就是说至少还有100亿吨左右的储量亟待我们进一步勘探发现。……有资料显示，我国的石油日消费量已达约548万桶，仅次于美国。……我国石油储备的情况是：长输管储存量为2～5天，铁路运输储量为7～15天，水路运输储量为15～25天，石油系统内部原油的综合储量为21.6天。以上均为生产性储备，没有战略储备。（国际能源机构要求其成员国建立可供90天需求的石油储备，发达国家一般有120～200天的战略储备。）下表是我国石油长期供需平衡状况。\n根据《石油与国家安全》和《中国国家战略问题报告》整理\n（1）结合材料1，简要分析世界石油经济战略态势的特点。\n（2）结合材料1、2，分析我国可持续发展的能源战略面临的问题和解决的途径。\n\n[表格数据]\n年 份 | 1989 | 1992 | 1995 | 1996 | 1997 | 1998 | 1999 | 2000 | 2001 | 2001 | 2003\nGDP 增长率 / 就业增长率 / 就业弹性系数 | 4.1 / 1.83 / 0.446 | 14.2 / 1.01 / 0.071 | 10.5 / 0.90 / 0.086 | 9.6 / 1.30 / 0.135 | 8.8 / 1.26 / 0.143 | 7.8 / 1.17 / 0.150 | 7.1 / 1.07 / 0.151 | 8.0 / 0.98 / 0.123 | 7.5 / 1.30 / 0.173 | 8.0 / 0.98 / 0.123 | 7.8 / 0.90 / 0.115\n\n地区 | 世界石油资源分布 / （亿桶） | 世界石油生产 / （万桶 / 天） | 世界石油消费 / （万桶 / 天） | 世界石油贸易 | 世界石油贸易\n地区 | 世界石油资源分布 / （亿桶） | 世界石油生产 / （万桶 / 天） | 世界石油消费 / （万桶 / 天） | 进口量 | 出口量\n中 东 | 7359 | 2045 | 420 | 50 | 1471\n北 美 | 272 | 719 | 2233 | 1124 | 158\n西 欧 | 184 | 563 | 1390 | 1164 | 437\n亚 太 | 459 | 708 | 2086 | 1351 | 219\n东 欧 | 883 | 994 | 506 | 99 | 648\n拉 美 | 1164 | 954 | 619 | 188 | 477\n非 洲 | 1055 | 727 | 236 | 73 | 597\n\n项 目 | 2000 年 | 2010 年 | 2020 年 | 2050 年\n国内需求量 | 2.0 | 3.0 | 4.0 | 5.0\n国内产量 | 1.6 | 1.7 | 1.8 | 1.0\n供需缺口 | 0.4 | 1.3 | 2.2 | 4.0"
