    "text": "新中国成立前夕，朱德在全国工会工作会议上的讲话中指出：“私人资本主义企业中的职工，他们在经济上还没有获得完全解放，他们还受着资本家剥削，这种剥削在新民主主义时期只能够受到限制，而不能够消灭”；为了工人阶级根本的长远的利益，还必须“在现阶段自觉地忍受资本家之一定限度以内的剥削”。\n根据以上材料回答问题：\n（1）新中国成立后,工人阶级成了国家的主人,为什么私人资本主义企业中的职工还要“忍受”资本家的剥削? (5分)\n （2）既然如此,为什么从1953年开始又要对私人资本主义进行社会主义改造? (5分)"
