    "number": 37,
    "subject": "思修法基",
    "score": 10,
    "text": "建立健全与经济发展水平相适应的社会保障体系，是建成完善的社会主义市场经济体制的重要内容，是贯彻以人为本为核心的科学发展观、构建社会主义和谐社会的必然要求。\n胡锦涛同志《在省部级主要领导干部提高构建社会主义和谐社会能力专题研讨班上的讲话》中指出：“我们所要建设的社会主义和谐社会，应该是民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然和谐相处的社会。”而要“切实维护和实现社会公平和正义”，其中一项重要内容就是“进一步完善社会保障体系，逐步扩大社会保障的覆盖面，切实保障各方面困难群众的基本生活，让他们感受到社会主义大家庭的温暖”。\n根据以上材料回答问题：\n（1）从我国社会保障体系的主要内容说明，为何建立健全社会保障体系体现着科学发展观以人为本的本质和核心？(5分)\n （2）公平正义是社会主义和谐社会的重要特征。从社会保障的基本功能说明建立健全社会保障体系与实现公平正义之间的内在联系。(5分)"
