    "id": "real-2007-q34",
    "year": 2007,
    "number": 34,
    "subject": "马原",
    "score": 10,
    "text": "成仿吾是无产阶级革命家，马克思主义理论家、教育家，他是由“文化人”成为“革命人”的典型之一，成仿吾到底是个什么样的人呢？作家丁玲在与其谋面之前曾产生过一系列的“合理想象”：“在文学上，他主张浪漫主义，创造社最早就是这样主张的；他是从日本留学回来的，一定很洋气，很潇洒，因为曾见过一些傲气十足的诗人，趾高气扬，高谈阔论；他在国外学军械制造，或许是个庄重严肃之人；他在黄埔军校担任教官；一定有一种军人气概；他曾经跟鲁迅进行过革命文学队伍内部的文学论争，写过火气很重的文章，是不是有点张飞、李逵式的气质呢？”后来丁玲在陕北见到成仿吾时，第一个感觉就是：“我想象的全错了”，原来，成仿吾是一个“土里土气，老实巴交”的普通人，一个尊重别人、热情、虚心、平等待人的人。丁玲十分后悔：“为什么我单单忽略了他是一个经过长征的革命老干部、红军战士，一个正派憨厚的共产党员呢？”\n另据老红军杨定华回忆说，在长征中见到的成仿吾完全是士兵的装扮：破旧的棉军衣，斜挎干粮袋，手持着一枝手杖。杨定华说，成仿吾在红军大学当政治教员。有人说出他的名字，但谁也不知道他是文学家。\n请运用马克思主义认识论基本原理加以分析：\n（1）丁玲对成仿吾的“合理想象”为什么“全错了”？\n（2）丁玲对成仿吾认识的“转变”过程对我们正确认识事物有何启示？"
