    const ITEMS = [
      { id: 'mayuan', subject: '马原', title: '马原 · 分析题', desc: '哲学、政治经济学、科学社会主义', group: 'analysis' },
      { id: 'maozhongte', subject: '毛中特', title: '毛中特 · 分析题', desc: '毛泽东思想与中国特色社会主义理论体系', group: 'analysis' },
      { id: 'shigang', subject: '史纲', title: '史纲 · 分析题', desc: '中国近现代史纲要', group: 'analysis' },
      { id: 'sixiu', subject: '思修法基', title: '思修法基 · 分析题', desc: '思想道德与法治', group: 'analysis' },
      { id: 'dangdai', subject: '当代', title: '当代 · 分析题', desc: '当代世界经济与政治', group: 'analysis' },
      { id: 'bianxi', subject: '辨析题', title: '辨析题', desc: '2003—2005 年旧题型', group: 'special' },
      { id: 'comprehensive', subject: '综合', title: '综合套题', desc: '按年份成套练习，整套批改', group: 'special' },
    ]

    const ITEM_MAP = Object.fromEntries(ITEMS.map((item) => [item.id, item]))

    const YEAR_SETS = (() => {
      const map = new Map()
      for (const question of REAL_QUESTIONS) {
        if (!map.has(question.year)) map.set(question.year, [])
        map.get(question.year).push(question)
      }
      return [...map.entries()]
        .sort((a, b) => b[0] - a[0])
        .map(([year, questions]) => {
          questions.sort((a, b) => a.number - b.number)
          return {
            id: `set-${year}`,
            kind: 'set',
            year,
            subject: '综合',
            title: `${year} 年主观题套题`,
            score: questions.reduce((sum, question) => sum + question.score, 0),
            questions,
            text: questions
              .map((question) => `第 ${question.number} 题（${question.subject}，${question.score} 分）\n${question.text}`)
              .join('\n\n'),
          }
        })
    })()

    const QUESTIONS_BY_SUBJECT = (() => {
      const map = {}
      for (const question of REAL_QUESTIONS) {
        if (!map[question.subject]) map[question.subject] = []
        map[question.subject].push(question)
      }
      for (const subject of Object.keys(map)) {
        map[subject].sort((a, b) => b.year - a.year || b.number - a.number)
      }
      return map
    })()

    function topicsFor(item) {
      if (!item) return []
      if (item.id === 'comprehensive') return YEAR_SETS
      return QUESTIONS_BY_SUBJECT[item.subject] || []
    }

    function questionLabel(question) {
      if (!question) return ''
      if (question.kind === 'set') return question.title
      return `${question.year} 年第 ${question.number} 题`
    }

    function questionPreview(question) {
      if (!question) return ''
      const raw = question.kind === 'set'
        ? question.questions.map((row) => `第${row.number}题：${row.text}`).join(' ')
        : question.text
      return raw.replace(/\s+/g, ' ').trim().slice(0, 180)
    }

    function countCjk(text) {
      const matches = String(text || '').match(/[\u4e00-\u9fff]/g)
      return matches ? matches.length : 0
    }

    function formatDate(ts) {
      try {
        return new Date(ts).toLocaleString('zh-CN', {
          month: '2-digit',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
        })
      } catch {
        return ''
      }
    }

    function scorePct(score, maxScore) {
      if (!Number.isFinite(Number(score)) || !Number.isFinite(Number(maxScore)) || Number(maxScore) <= 0) return 0
      return Math.round((Number(score) / Number(maxScore)) * 100)
    }

    function emptyItem() {
      return { best: 0, attempts: 0 }
    }

    function emptyItems() {
      const items = {}
      for (const item of ITEMS) items[item.id] = emptyItem()
      return items
    }

    function emptyState() {
      return { version: 1, items: emptyItems(), history: [], updatedAt: 0 }
    }

    function normalizeState(value) {
      const base = emptyState()
      if (!value || typeof value !== 'object') return base
      const items = { ...base.items }
      if (value.items && typeof value.items === 'object') {
        for (const item of ITEMS) {
          const src = value.items[item.id]
          if (!src || typeof src !== 'object') continue
          items[item.id] = {
            best: Math.max(0, Number(src.best) || 0),
            attempts: Math.max(0, Number(src.attempts) || 0),
          }
        }
      }
      return {
        version: 1,
        items,
        history: Array.isArray(value.history) ? value.history.slice(0, 80) : [],
        updatedAt: Number(value.updatedAt) || 0,
      }
    }

    function loadState() {
      try {
        const raw = window.localStorage.getItem(STORAGE_KEY)
        if (!raw) return emptyState()
        return normalizeState(JSON.parse(raw))
      } catch {
        return emptyState()
      }
    }

    function saveState(state) {
      try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...state, updatedAt: Date.now() }))
      } catch {
        /* keep in-memory state */
      }
    }

    function loadDraft() {
      try {
        const raw = window.localStorage.getItem(DRAFT_KEY)
        return raw ? JSON.parse(raw) : null
      } catch {
        return null
      }
    }

    function patchDraft(patch) {
      try {
        const current = loadDraft() || {}
        window.localStorage.setItem(DRAFT_KEY, JSON.stringify({ ...current, ...patch, savedAt: Date.now() }))
      } catch {
        /* ignore */
      }
    }

    function clearDraft() {
      try {
        window.localStorage.removeItem(DRAFT_KEY)
      } catch {
        /* ignore */
      }
    }

    async function getJson(url, init) {
      const response = await fetch(url, init)
      let data = null
      try {
        data = await response.json()
      } catch {
        data = null
      }
      if (!response.ok || !data || data.ok === false) {
        throw new Error((data && data.error) || 'HTTP ' + response.status)
      }
      return data
    }

    function postJson(url, body) {
      return getJson(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body || {}),
      })
    }

